package com.footballacademy.services.scouting;
import com.footballacademy.model.*; import com.footballacademy.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service public class VideoAnalysisService { private final VideoAssetRepository assets; private final VideoAnalysisRepository analyses; public VideoAnalysisService(VideoAssetRepository assets, VideoAnalysisRepository analyses){this.assets=assets;this.analyses=analyses;} @Transactional public VideoAnalysis startAnalysis(Long videoAssetId){VideoAsset asset=assets.findById(videoAssetId).orElseThrow(); VideoAnalysis a=analyses.findByVideoAsset_Id(videoAssetId).orElse(new VideoAnalysis()); a.setVideoAsset(asset); a.setStatus(VideoAnalysisStatus.PROCESSING); a.setDetectedEvents(0); return analyses.save(a);} public String getHighlights(Long videoAssetId){return analyses.findByVideoAsset_Id(videoAssetId).map(VideoAnalysis::getHighlightUrl).orElse(null);} public String getHeatmap(Long videoAssetId){return analyses.findByVideoAsset_Id(videoAssetId).map(VideoAnalysis::getHeatmapUrl).orElse(null);} @Transactional public VideoAnalysis complete(Long videoAssetId, String heatmapUrl, String highlightUrl, Double score){VideoAnalysis a=analyses.findByVideoAsset_Id(videoAssetId).orElseThrow(); a.setStatus(VideoAnalysisStatus.COMPLETED); a.setHeatmapUrl(heatmapUrl); a.setHighlightUrl(highlightUrl); a.setAnalysisScore(score); a.setCompletedAt(LocalDateTime.now()); return analyses.save(a);} }
